<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave,useRoute,useRouter} from 'vue-router';
import {api,get,message} from '../api';import {useAuth} from '../stores/auth';import {agents,agentByCode} from '../agents';import {date} from '../fulfillment';
import AgentAnswerText from '../components/AgentAnswerText.vue';
import Icon from '../components/Icon.vue';import AgentPlanConfirmation from '../components/AgentPlanConfirmation.vue';import AgentPlanResult from '../components/AgentPlanResult.vue';import AgentAnalysisResult from '../components/AgentAnalysisResult.vue';import AgentDocumentWorkspace from '../components/AgentDocumentWorkspace.vue';
const route=useRoute(),router=useRouter(),auth=useAuth();const context=ref<any>(),options=ref<any>({nodes:[],grains:[]}),conversation=ref<any>(),history=ref<any[]>([]),historyTotal=ref(0),historyPage=ref(1),historyQuery=ref(''),historyError=ref(''),historyBusy=ref(false),loading=ref(false),busy=ref(false),error=ref(''),question=ref(''),capability=ref(''),contextType=ref('page'),contextId=ref(''),tasks=ref<any[]>([]),taskBusy=ref(false),help=ref(false),messagesEl=ref<HTMLElement>(),sidebarOpen=ref(false),pendingQuestion=ref(''),expandedPlans=ref<string[]>([]);
const documentBusy=ref(false),stopping=ref(false),operationNote=ref('');
let historyTimer:ReturnType<typeof setTimeout>|undefined,operationKey='',loadGeneration=0,historyGeneration=0,taskGeneration=0,retryKind='load',lastSolve:{input:any,key:string}|undefined;
const locked=computed(()=>busy.value||documentBusy.value);
function errorMessage(e:any){return e?.response||e?.code?message(e):e?.message||message(e);}
async function persistRoute(){await router.replace({path:'/agents',query:{conversation:conversation.value.id}});}
async function retry(){if(retryKind==='solve'&&lastSolve)await confirmPlan(lastSolve.input);else if(retryKind==='send')await send();else await load();}
async function stop(){if(!conversation.value||stopping.value)return;stopping.value=true;try{const r=(await api.post('/agents/center/conversations/'+conversation.value.id+'/cancel')).data.data;operationNote.value=r.status==='FINISHING'?'路线已生成，正在保存分析结果…':'正在停止分析，已保留输入条件…';}catch(e){error.value=errorMessage(e);stopping.value=false;}}
const available=computed(()=>agents.filter(a=>context.value?.capabilities.some((c:string[])=>c[0]===a.code)));const activeAgent=computed(()=>agentByCode(capability.value||'PLAN'));const home=computed(()=>!capability.value&&!conversation.value);const square=computed(()=>route.query.view==='square');const turns=computed(()=>conversation.value?.turns||[]);const draftKey=computed(()=>`liaoliang-agent-draft:${auth.user?.id}:${conversation.value?.id||capability.value||'home'}`);const taskId=computed(()=>contextType.value==='task'?contextId.value:'');
async function historyLoad(more=false){const generation=++historyGeneration;historyBusy.value=true;historyError.value='';try{const page=more?historyPage.value+1:1;const data=await get('/agents/center/conversations',{page,pageSize:20,q:historyQuery.value});if(generation!==historyGeneration)return;history.value=more?[...history.value,...data.items]:data.items;historyTotal.value=data.total;historyPage.value=page;}catch(e){if(generation===historyGeneration)historyError.value=errorMessage(e);}finally{if(generation===historyGeneration)historyBusy.value=false;}}
async function load(){const generation=++loadGeneration;loading.value=true;error.value='';retryKind='load';lastSolve=undefined;try{
 if(!context.value){context.value=await get('/agents/context');if(auth.can('plan:read'))options.value=await get('/plans/options');await historyLoad();}
 const id=typeof route.query.conversation==='string'?route.query.conversation:'';
 const current=id?await get('/agents/center/conversations/'+id):undefined;if(generation!==loadGeneration)return;
 conversation.value=current;capability.value=current?.capability||String(route.query.agent||'');if(capability.value&&!available.value.some(a=>a.code===capability.value))throw new Error('当前账号无权使用该智能体');
 contextType.value=current?.contextType||String(route.query.contextType||'page');contextId.value=current?.contextId||String(route.query.contextId||'');question.value=String(route.query.question||localStorage.getItem(draftKey.value)||'');expandedPlans.value=[];
 if(current?.turns?.length){const lastPlan=[...current.turns].reverse().find((v:any)=>v.response.type==='PLAN_RESULT');if(lastPlan)expandedPlans.value=[lastPlan.id];}
 if(auth.can('tracking:read')&&capability.value!=='PLAN'){await searchTasks('');if(contextType.value==='task'&&!tasks.value.some(t=>t.id===contextId.value)){const selected=await get('/tracking/tasks/'+contextId.value);tasks.value.unshift(selected);}}await scrollMessages();
 }catch(e){error.value=errorMessage(e);}finally{if(generation===loadGeneration)loading.value=false;}}
async function scrollMessages(){await nextTick();messagesEl.value?.scrollTo({top:messagesEl.value.scrollHeight,behavior:'instant'});}
async function choose(code:string){if(locked.value)return;sidebarOpen.value=false;await router.push({path:'/agents',query:code?{agent:code}:{}});}
async function showSquare(){if(busy.value)return;sidebarOpen.value=false;await router.push({path:'/agents',query:{view:'square'}});}
async function openHistory(id:string){if(busy.value)return;sidebarOpen.value=false;await router.push({path:'/agents',query:{conversation:id}});}
async function newConversation(){await choose(capability.value);}
async function searchTasks(q:string){const generation=++taskGeneration;taskBusy.value=true;try{const result=await get('/agents/center/tasks',{q,pageSize:20});if(generation===taskGeneration)tasks.value=result.items;}catch(e){if(generation===taskGeneration)error.value=errorMessage(e);}finally{if(generation===taskGeneration)taskBusy.value=false;}}
async function chooseTask(id:string){if(locked.value)return;await router.push({path:'/agents',query:{agent:capability.value||'TRACK',...(id?{contextType:'task',contextId:id}:{})}});}
function detect(text:string){if(/单据|磅单|签收单|设备交接|识别/.test(text))return 'DOCUMENT';if(/港口|拥堵|候港/.test(text))return 'PORT';if(/天气|海况|环境|台风|大风/.test(text))return 'ENVIRONMENT';if(/ETA|预计.*到|延误|何时.*到|什么时候.*到/i.test(text))return 'ETA';if(/路线|方案|联运|运输到|运送到|运到|发往|怎么走/.test(text)||(/吨|玉米|小麦|稻谷|大豆/.test(text)&&/从.*(?:到|至)|→/.test(text)))return 'PLAN';return 'TRACK';}
async function ensureConversation(){if(conversation.value)return;const c=(await api.post('/agents/center/conversations',{capability:capability.value,contextType:contextType.value,contextId:contextId.value})).data.data;conversation.value={...c,turns:[]};}
async function send(){const text=question.value.trim();if(text.length<2||locked.value)return;const oldDraft=draftKey.value;if(!capability.value)capability.value=detect(text);if(!available.value.some(a=>a.code===capability.value)){error.value='当前账号未开通这项能力，请选择已授权智能体';return;}busy.value=true;stopping.value=false;operationNote.value='';error.value='';retryKind='send';pendingQuestion.value=text;operationKey||=crypto.randomUUID();try{
 await ensureConversation();localStorage.setItem(draftKey.value,text);await persistRoute();const turn=(await api.post('/agents/center/conversations/'+conversation.value.id+'/messages',{question:text,requestKey:operationKey},{timeout:185000})).data.data;if(!turns.value.some((v:any)=>v.id===turn.id))conversation.value.turns.push(turn);if(conversation.value.title==='新对话')conversation.value.title=text.slice(0,50);question.value='';pendingQuestion.value='';operationKey='';localStorage.removeItem(oldDraft);localStorage.removeItem(draftKey.value);await historyLoad();await scrollMessages();
 }catch(e){error.value=errorMessage(e);}finally{busy.value=false;stopping.value=false;pendingQuestion.value='';}}
async function confirmPlan(input:any){if(locked.value)return;busy.value=true;stopping.value=false;operationNote.value='';error.value='';retryKind='solve';pendingQuestion.value='确认运输条件，生成联运方案';if(!lastSolve||JSON.stringify(lastSolve.input)!==JSON.stringify(input))lastSolve={input:JSON.parse(JSON.stringify(input)),key:crypto.randomUUID()};try{const turn=(await api.post('/agents/center/conversations/'+conversation.value.id+'/solve',{requestKey:lastSolve.key,input},{timeout:220000})).data.data;if(!turns.value.some((v:any)=>v.id===turn.id))conversation.value.turns.push(turn);expandedPlans.value.push(turn.id);lastSolve=undefined;await historyLoad();await scrollMessages();}catch(e){error.value=errorMessage(e);}finally{busy.value=false;stopping.value=false;pendingQuestion.value='';}}
function example(text:string){if(!busy.value){question.value=text;}}
function togglePlan(id:string){expandedPlans.value=expandedPlans.value.includes(id)?expandedPlans.value.filter(v=>v!==id):[...expandedPlans.value,id];}
watch(question,v=>{if(!busy.value){localStorage.setItem(draftKey.value,v.slice(0,2000));operationKey='';}});
watch(historyQuery,()=>{clearTimeout(historyTimer);historyTimer=setTimeout(()=>historyLoad(),350);});watch(()=>route.fullPath,()=>{if(busy.value&&route.query.conversation===conversation.value?.id)return;load();},{immediate:true});
onBeforeRouteLeave(()=>!locked.value);onBeforeUnmount(()=>clearTimeout(historyTimer));
</script>
<template><div class="agent-center"><a class="skip-link" href="#agent-main">跳到智能体工作区</a><aside class="agent-sidebar" :class="{visible:sidebarOpen}"><button class="agent-brand" aria-label="返回智能体中心首页" :disabled="locked" @click="choose('')"><img src="/agent/liaoliang-ai.png?v=9c956ad9c5e5" alt="辽粮智能体"/><span><strong>辽粮智运</strong><small>AI 智能体中心</small></span></button><el-button class="new-chat" type="primary" :disabled="locked" @click="newConversation"><Icon name="plus" :size="16"/>新建对话</el-button><nav aria-label="智能体中心导航"><button :class="{current:home&&!square}" :disabled="locked" @click="choose('')"><Icon name="house"/>首页</button><button :class="{current:square}" :disabled="locked" @click="showSquare"><Icon name="bot"/>智能体广场<span>6</span></button></nav><div class="history-heading"><span>历史对话</span><el-button link aria-label="刷新对话列表" :disabled="busy" :loading="historyBusy" @click="historyLoad()"><Icon name="refresh" :size="14"/></el-button></div><el-input v-model="historyQuery" aria-label="搜索历史对话" placeholder="搜索历史对话" clearable size="small"/><div class="agent-history"><p v-if="historyError" class="history-error">{{historyError}} <button @click="historyLoad()">重试</button></p><button v-for="h in history" :key="h.id" :class="{selected:conversation?.id===h.id}" :disabled="locked" @click="openHistory(h.id)"><Icon :name="agentByCode(h.capability).icon" :size="14"/><span>{{h.title}}</span><small>{{date(h.updatedAt).split(' ')[0]}}</small></button><p v-if="!history.length&&!historyBusy&&!historyError" class="history-empty">开始对话后，记录将保存在这里。</p><el-button v-if="history.length<historyTotal" link :loading="historyBusy" @click="historyLoad(true)">加载更多</el-button></div><div class="sidebar-bottom"><button @click="help=true"><Icon name="book" :size="17"/>使用指南</button><router-link to="/workbench" :class="{disabled:locked}"><Icon name="external" :size="17"/>返回业务系统</router-link><div class="agent-account"><span>{{auth.user?.displayName?.slice(0,1)}}</span><div><strong>{{auth.user?.displayName}}</strong><small>{{context?.entityName}}</small></div></div></div></aside><main id="agent-main" class="agent-workspace"><header class="agent-topbar"><el-button class="mobile-menu" aria-label="打开智能体导航" @click="sidebarOpen=!sidebarOpen"><Icon name="more"/></el-button><el-select v-if="!home" v-model="capability" aria-label="切换智能体" :disabled="locked" @change="choose"><el-option v-for="a in available" :key="a.code" :label="a.name" :value="a.code"/></el-select><span v-else class="workspace-label">{{square?'智能体广场':'辽粮智能助手'}}</span><span class="conversation-title">{{conversation?.title||(!home?'新对话':'')}}</span><router-link to="/account" class="account-avatar" :class="{disabled:locked}" aria-label="账号设置">{{auth.user?.displayName?.slice(0,1)}}</router-link></header><el-alert v-if="error" class="center-error" :title="error" type="error" :closable="false"><el-button link :disabled="busy" @click="retry">重试</el-button></el-alert><div v-if="loading" class="agent-loading"><el-skeleton :rows="6" animated/></div><template v-else-if="context"><div v-if="home" class="agent-home"><section v-if="!square" class="agent-hero"><div><p>辽粮智运</p><h1>让粮食联运更清晰</h1><span>从路线规划到运输跟踪，六个智能体协助您处理业务。</span></div><img src="/agent/liaoliang-ai.png?v=9c956ad9c5e5" alt="辽粮AI智能体"/></section><section v-else class="square-intro"><h1>智能体广场</h1><p>按业务场景选择智能体，查看使用方法后开始对话。</p></section><form v-if="!square" class="home-composer" @submit.prevent="send"><el-input v-model="question" aria-label="向辽粮智能助手提问" type="textarea" :rows="2" :maxlength="2000" :disabled="busy" placeholder="规划盘锦到广州的 1000.0 吨玉米多式联运路线" @keydown.ctrl.enter.prevent="send"/><footer><span><Icon name="bot" :size="16"/>辽粮智能助手</span><el-button type="primary" :loading="busy" :disabled="question.trim().length<2||documentBusy" native-type="submit" aria-label="发送问题"><Icon name="arrow" :size="20"/></el-button></footer></form><div class="agent-cards"><button v-for="a in available" :key="a.code" :disabled="locked" @click="choose(a.code)"><span class="agent-icon" :style="{background:a.color}"><Icon :name="a.icon" :size="24"/></span><div><strong>{{a.name}}</strong><p>{{a.brief}}</p></div><Icon name="arrow" class="card-arrow" :size="18"/></button></div><div v-if="busy" class="home-progress" role="status">{{capability==='PLAN'?'正在识别运输条件和装卸位置…':'正在读取业务记录并整理分析…'}}</div></div><div v-else class="agent-chat"><div ref="messagesEl" class="agent-messages" role="log" aria-label="智能体对话" tabindex="0"><section v-if="!turns.length" class="agent-welcome"><span class="welcome-icon" :style="{background:activeAgent.color}"><Icon :name="activeAgent.icon" :size="24"/></span><h1>{{activeAgent.name}}</h1><p>{{activeAgent.intro}}</p><div class="welcome-guidance"><section><h3>需要提供什么</h3><p>{{activeAgent.inputs}}</p></section><section><h3>如何得到结果</h3><p>{{activeAgent.method}}</p></section></div><h3 class="example-title">可以这样问我</h3><button v-for="text in activeAgent.examples" :key="text" class="prompt-example" :disabled="busy" @click="example(text)"><span>{{text}}</span><Icon name="arrow" :size="16"/></button></section><div v-if="contextType!=='page'" class="context-strip"><Icon name="file" :size="14"/>{{contextType==='task'?'已关联运输任务':contextType==='transport-demand'?'已关联运输需求':'已关联业务对象'}}<span>{{tasks.find(t=>t.id===contextId)?.businessNo||conversation?.planDraft?.businessNo||''}}</span></div><section v-for="(turn,i) in turns" :key="turn.id" class="chat-turn"><div class="user-message">{{turn.question}}</div><div class="assistant-message"><span class="answer-avatar"><Icon :name="activeAgent.icon" :size="19"/></span><article><AgentAnswerText :text="turn.response.summary"/><AgentPlanConfirmation v-if="turn.response.type==='PLAN_CONFIRM'" :draft="turn.response.draft" :options="options" :busy="busy" :disabled="i!==turns.length-1||!auth.can('plan:solve')" @confirm="confirmPlan"/><template v-if="turn.response.type==='PLAN_RESULT'&&turn.response.plan"><AgentPlanResult v-if="expandedPlans.includes(turn.id)" :plan="turn.response.plan"/><el-button v-else link type="primary" @click="togglePlan(turn.id)">展开路线、地图和费用比较</el-button></template><AgentAnalysisResult v-if="turn.response.type==='ANALYSIS'" :result="turn.response"/><footer class="answer-footer">{{date(turn.createdAt)}}<span v-if="turn.response.status==='DEGRADED'">当前展示业务记录与规则分析</span></footer></article></div></section><div v-if="pendingQuestion" class="user-message pending-message">{{pendingQuestion}}</div><div v-if="busy" class="chat-progress" role="status"><span class="progress-dot"/>{{operationNote||(pendingQuestion==='确认运输条件，生成联运方案'?'正在组合联运通道并比较可靠性、成本和时效…':capability==='PLAN'?'正在识别运输条件和核对装卸地址…':'正在读取业务记录并整理分析…')}}<el-button link type="primary" :disabled="stopping" @click="stop">{{stopping?'正在停止':'停止分析'}}</el-button></div><AgentDocumentWorkspace v-if="capability==='DOCUMENT'&&taskId" :key="taskId" :task-id="taskId" @busy="documentBusy=$event"/></div><footer class="chat-compose-area"><div v-if="capability!=='PLAN'&&auth.can('tracking:read')" class="task-context"><label>关联运输任务</label><el-select :model-value="taskId" filterable remote clearable :remote-method="searchTasks" :loading="taskBusy" :disabled="locked" aria-label="关联运输任务" placeholder="搜索运单号、合同号、任务号或车牌" @change="chooseTask"><el-option v-if="taskId&&!tasks.some(t=>t.id===taskId)" :value="taskId" :label="taskId"/><el-option v-for="t in tasks" :key="t.id" :value="t.id" :label="t.businessNo+' · '+t.origin+' → '+t.destination"/></el-select></div><form class="chat-composer" @submit.prevent="send"><el-input v-model="question" aria-label="向智能体提问" type="textarea" :rows="2" :maxlength="2000" :disabled="busy" :placeholder="'向'+activeAgent.name+'提问，Ctrl + Enter 发送'" @keydown.ctrl.enter.prevent="send"/><footer><span>{{context.scope}}</span><el-button type="primary" :disabled="question.trim().length<2||documentBusy" :loading="busy" native-type="submit">发送<Icon name="arrow" :size="16"/></el-button></footer></form></footer></div></template></main><el-dialog v-model="help" title="使用辽粮智运" width="620px"><div class="agent-help"><p>在首页直接描述业务问题，或从智能体广场选择能力。各智能体会提供提问方式和所需信息。</p><p>联运求解先确认运输条件与装卸位置，再展示路线、费用和地图；点击“查看更多路径推荐”可进入方案求解并继续发布。</p><p>运输跟踪、ETA和单据分析可选择关联任务。历史对话仅在当前账号中显示，数据范围沿用业务权限。</p><p>单据识别结果支持人工复核，确认值会保存至对应单据记录。</p></div><template #footer><el-button @click="help=false">知道了</el-button></template></el-dialog></div></template>
<style scoped>
